def sentence_count(text: str) -> int:
    return len([x for x in re.split(r'[۔؟?!]+', text) if x.strip()])

def make_target(key, text):
    form, pos, sense, strategy = LEX[key]
    n = text.count(form)
    assert n >= 1, (key, form, n)
    return {'id':f'ur-c1-u02-{key}','form':form,'lemma':form,'part_of_speech':pos,'intended_sense':sense,'register':'professional/contemporary standard','context_strategy':[strategy,'professional_judgment','inference_chain'],'first_introduced':True,'exposures_in_text':n,'variety':'standard Urdu','sense_verification':'Dictionary/usage sense independently checked during 2026-08-26 generation pass; formal release evidence remains separate.'}

def build_records():
    out=[]; prior=[]
    for i,s in enumerate(SPECS,1):
        text=s['text']; new=[make_target(k,text) for k in s['lex']]; reviews=[]
        if s['role']=='checkpoint':
            for k in prior:
                form=LEX[k][0]; assert form in text, (k,form)
                reviews.append({'id':f'ur-c1-u02-{k}','form':form,'review_stage':'R1','representation':'running_text'})
        else: prior.extend(s['lex'])
        questions=[]; answers=[]
        for n,q in enumerate(s['qs'],1):
            qtype,prompt,answer,*target=q
            qd={'id':f'q{n}','type':qtype,'prompt':prompt,'answer_id':f'a{n}'}
            if target: qd['target_ids']=[f'ur-c1-u02-{target[0]}']
            questions.append(qd); answers.append({'id':f'a{n}','question_id':f'q{n}','answer':answer,'explanation':''})
        rec={'id':s['id'],'language':'ur','cefr':'C1','unit':2,'sequence':s['sequence'],'revision':1,'title':s['title'],'passage_type':'checkpoint' if s['role']=='checkpoint' else s['role'],'genre':s['genre'],'domains':['professional','public'] if i in (1,2,4,5,6) else ['professional','educational'],'topics':['professional judgment'],'text':text,'word_count':len(text.split()),'sentence_count':sentence_count(text),'estimated_known_token_coverage':0,'new_lexical_targets':new,'review_lexical_targets':reviews,'grammar_targets':[{'id':f'ur-c1-u02-grammar-{i:02d}','role':'integration','description':'Use qualification, exception, scope, and conditional reasoning to calibrate professional decisions.'}],'discourse_targets':[{'id':f'ur-c1-u02-discourse-{i:02d}','role':'integration','description':'Reconstruct decision criteria, trade-offs, uncertainty, justification, and accountability across paragraphs.'}],'questions':questions,'answer_key':answers,'speed_training':{'timed':False,'benchmark_eligible':False,'comprehension_gate':0.8,'new_word_policy':'recycling_only' if s['role']=='checkpoint' else 'controlled','notes':'C1 generation-stage passage; formal fluency decision deferred to final audit.'},'quality':{'status':'draft','schema_check':'pending','coverage_check':'pending','linguistic_review':'pending','pedagogical_review':'pending','answer_key_check':'pending','fact_check':'not_required','notes':['Fictional/professional Urdu C1 generation-stage draft; lexical senses were independently checked at generation time, while formal educator/publication audit remains separate.']},'reader_tags':[f"unit_role:{'checkpoint' if s['role']=='checkpoint' else s['role']}",'generation_batch','c1'],'difficulty_notes_internal':'C1 Unit 02 generation draft: professional judgment with multi-step cross-paragraph inference, criteria trade-offs, exception handling, and accountable recommendation.','complexity_profile':{'inference_depth':'multi_step_cross_paragraph','morphology_notes':'C1 Urdu with professional register, abstract nominal language, conditional qualification, and decision reasoning.'}}
        out.append(rec)
    assert prior==['l01','l02','l03','l04','l05','l06','l07','l08','l09','l10']
    return out

def validate_new(records):
    errors=[]
    if [r['sequence'] for r in records]!=list(range(7,13)): errors.append('sequence')
    if len({r['id'] for r in records})!=6: errors.append('ids')
    roles=['instructional','reinforcement','interleaved','transfer','integration','checkpoint']
    if [r['passage_type'] for r in records]!=roles: errors.append('roles')
    for r in records:
        if len(r['questions'])!=10 or len(r['answer_key'])!=10: errors.append(r['id']+':qa_count')
        amap={a['id']:a for a in r['answer_key']}
        for q in r['questions']:
            if q['answer_id'] not in amap or amap[q['answer_id']]['question_id']!=q['id']: errors.append(r['id']+':link')
        for t in r['new_lexical_targets']:
            if r['text'].count(t['form'])!=t['exposures_in_text']: errors.append(r['id']+':exposure:'+t['form'])
        if r['word_count']!=len(r['text'].split()): errors.append(r['id']+':words')
        if r['sentence_count']!=sentence_count(r['text']): errors.append(r['id']+':sentences')
    return errors

def must_replace(text, old, new, label):
    if old not in text: raise SystemExit(f'missing expected state text: {label}')
    return text.replace(old,new)

def apply():
    records=build_records(); errors=validate_new(records)
    if errors: raise SystemExit('new-record validation failed: '+repr(errors))
    p=ROOT/'reading/urdu/c1/passages.jsonl'; existing=p.read_text(encoding='utf-8').splitlines(); parsed=[json.loads(x) for x in existing if x.strip()]
    if len(parsed)!=6 or parsed[-1].get('id')!='ur-c1-u01-p06' or parsed[-1].get('sequence')!=6: raise SystemExit('frontier drift: expected exactly Urdu C1 Unit 1 sequences 1-6')
    if any(r['id'].startswith('ur-c1-u02-') for r in parsed): raise SystemExit('Unit 2 already present')
    p.write_text('\n'.join(existing+[json.dumps(r,ensure_ascii=False,separators=(',',':')) for r in records])+'\n',encoding='utf-8')

    cont_path=ROOT/'reading/CONTINUATION.json'; cont=json.loads(cont_path.read_text(encoding='utf-8'))
