    hand_path.write_text(hand,encoding='utf-8')

    audit={'project_id':'LANG-A1C2','date':'2026-08-26','language':'ur','level':'C1','unit':2,'generation_only':True,'quality_promotion':False,'passages_added':6,'sequences':[7,8,9,10,11,12],'questions_added':60,'answers_added':60,'new_lexical_targets':10,'mechanical_checks':{'json_records':'PASS','sequence_roles':'PASS','qa_linkage':'PASS','target_exposures':'PASS','stored_counts':'PASS'},'lexical_note':'Advanced target senses checked independently during generation; no fabricated source ranks were assigned. Formal corpus-wide lexical/release evidence remains separate.','next_frontier':{'language':'urdu','level':'C1','unit':3,'sequence':13},'release_state_changed':False}
